"""MP_NORETURN void mp_raise_OSError(int errno_) {
    #ifdef PYGRAM_UNSUPPORTED_EXIT
    // pygram: the C half of the OSError subclass mapping (py/objexcept.c has
    // the Python half and the full reasoning). Every real OS failure in this
    // build — a missing file, a directory that already exists, a permission
    // denial — arrives here with ONE argument, which is below the 2..5 arity
    // CPython's OSError.__new__ maps on. So the type has to be chosen here
