SV = shim._strip_verbose
TOK = ["a"," ","#","#c\n","\\ ","\\#","\\\\","[ab]","[a b]","[^ ]","[#]","[\\]]","(",")","(?:","|","*","+","?",".","\\d","{2}","{2, 3}","{","}","^","$","\\","\\\n","b","1"]
