for _ in range(120000):
    p = "".join(random.choice(TOK) for _ in range(random.randint(1,6)))
    try: cp = re.compile(p, re.X); cpok=True
    except Exception: cpok=False
    try: rw = SV(p); cr = re.compile(rw); rwok=True
