// ---- the dispatcher: the mixture itself ------------------------------------

/// `mopy run ...` routes the program and runs it on the engine that fits.
///
/// Two properties make this cheap enough to be worth doing at all:
///
///   * **The winning case costs nothing.** A program routed to mopy runs
///     IN THIS PROCESS - no second spawn, no pipe, no serialisation. Since 96%
///     of a one-liner's cost is the OS spawning a process (docs/PYGRAM.md
///     section 8c), a dispatcher that spawned a child would give back most of
///     what the fast engine won.
///   * **Falling onward costs one `exec`, not one fork.** `exec` REPLACES this
///     process, so a mis-route costs the target interpreter's startup and
///     nothing else - no extra process ever exists.
///
/// The fallback is safe because of the commit barrier (`io.rs`): a mopy run
/// that ends in exit 90 has written no output and touched no file, so the next
/// engine starts from the same state mopy did.
fn dispatch(args: &[String]) -> i32 {
    let (src, tail, is_file) = match parse_run_args(args) {
        Ok(v) => v,
        Err(code) => return code,
    };
    let r = route::route(&src);
    if r.engine == route::Engine::Mopy {
        // Running in-process also means stdin is still unread at this point,
        // which a spawned child could not be given back.
        let code = execute(&src);
        if code != UNSUPPORTED_EXIT {
            return code;
        }
        // The route was optimistic and a value-dependent refusal fired: an
        // integer outgrew 64 bits, or a set's order was asked for. Fall onward.
        return exec_engine(engine_path(route::Engine::Pygram), &src, &tail, &is_file, true);
    }
    let onward = r.engine == route::Engine::Pygram;
    exec_engine(engine_path(r.engine), &src, &tail, &is_file, onward)
}

/// Parse the tail of `mopy run ...` into (program source, program args, file?).
fn parse_run_args(args: &[String]) -> Result<(String, Vec<String>, Option<String>), i32> {
    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "-c" => {
                let Some(src) = args.get(i + 1) else {
                    eprintln!("mopy: run -c needs a program");
                    return Err(2);
                };
                return Ok((src.clone(), args[i + 2..].to_vec(), None));
            }
            "-" => {
                let mut s = String::new();
                if std::io::stdin().read_to_string(&mut s).is_err() {
                    eprintln!("mopy: cannot read program from stdin");
                    return Err(2);
                }
                return Ok((s, args[i + 1..].to_vec(), None));
            }
            f if f.starts_with('-') => i += 1,
            path => match std::fs::read_to_string(path) {
                Ok(s) => return Ok((s, args[i + 1..].to_vec(), Some(path.to_string()))),
                Err(e) => {
                    eprintln!("mopy: can't open file '{path}': {e}");
                    return Err(2);
                }
            },
        }
    }
    eprintln!("mopy: run needs -c PROG, a FILE, or -");
    Err(2)
}

fn engine_path(e: route::Engine) -> String {
    match e {
        route::Engine::Pygram => std::env::var("MOPY_PYGRAM").unwrap_or_else(|_| "pygram".into()),
        route::Engine::CPython => std::env::var("MOPY_CPYTHON").unwrap_or_else(|_| "python3".into()),
        route::Engine::Mopy => std::env::args().next().unwrap_or_else(|| "mopy".into()),
    }
}

/// Replace this process with `bin`, running the same program. `exec` only
/// returns on failure; if the binary is absent we fall to the next tier rather
/// than reporting an error the caller cannot act on.
fn exec_engine(
    bin: String,
    src: &str,
    tail: &[String],
    is_file: &Option<String>,
    retry_cpython: bool,
) -> i32 {
    use std::os::unix::process::CommandExt;
    let mut cmd = std::process::Command::new(&bin);
    match is_file {
        Some(p) => {
            cmd.arg(p);
        }
        None => {
            cmd.arg("-c").arg(src);
        }
    }
    cmd.args(tail);
    let err = cmd.exec();
    if retry_cpython {
        let cp = engine_path(route::Engine::CPython);
        if cp != bin {
            return exec_engine(cp, src, tail, is_file, false);
        }
    }
    eprintln!("mopy: cannot run {bin}: {err}");
    127
}
