def run(mod, fn):
    try:
        return ("ok", fn(mod))
    except NotImplementedError as e:
        return ("unsupported", str(e))
    except Exception as e:
        return ("exc", type(e).__name__, str(e))

def cmp(label, fn, diffs, n):
    n[0]+=1
    a=run(real,fn); b=run(shim,fn)
    if a!=b:
        # normalise: shim's exit-90 refusal is allowed
        if b[0]=="unsupported": return
        diffs.append((label,a,b))

diffs=[]; n=[0]
QUO=[0,1,2,3]
ESC=[None,"\\","x"]
DQ=[True,False]
DEL=[",",";"]
QC=['"',"'"]
LT=["\r\n","\n","|"]
ROWS=[
 [], [""], ["",""], [None], ["a"], ["a","b"],
 ["a,b"], ['a"b'], ["a\\b"], ["a\nb"], ["a\rb"], ["a\r\nb"],
 ["a;b"], ["a'b"], ["ax b"], ["a|b"],
 [1], [2.5], [True], [False], [None,"x"], [1.0], [0.1],
 ["  a  "], ["\t"], ["åäö"], ["日本"], ["a\x00b"], ["퟿"],
 ["a"*3], [""], ["x"], ["\\"], ['"'], [","],
]
for q,e,dq,dl,qc,lt in itertools.product(QUO,ESC,DQ,DEL,QC,LT):
    kw=dict(quoting=q,escapechar=e,doublequote=dq,delimiter=dl,quotechar=qc,lineterminator=lt)
    for row in ROWS:
        def fn(mod,kw=kw,row=row):
            o=io.StringIO(); mod.writer(o,**kw).writerow(list(row)); return o.getvalue()
        cmp(("W",tuple(sorted(kw.items())),tuple(map(repr,row))), fn, diffs, n)

